"""
Build the complete new_data.tsv file from the hardcoded data.
This script writes all rows provided by the user.
"""
import os

# Each row is a list of tab-separated values following the GSheet column layout:
# 0:S.N  1:Received  2:TenderRef  3:PONo  4:Supplier  5:Country  6:LocalAgent
# 7:Desc  8:Unit  9:Qty  10:UnitPrice  11:TotalPrice  12:TotalPOAmt  13:Currency
# 14:Budget  15:ShipMode  16:POTransferred  17:PGReq  18:PGRecv  19:PGConf
# 20:Bank  21:PGRef  22:PGExpiry  23:RemDays  24:SubmitPG  25:Status
# 26:StatusDate  27:PGReceiver  28:BIOfficer  29:LCOpen  30:LCOpened
# 31:LCE expiry  32:LCAge  33:ShipOfficer  34:ShipStatus  35:OrderClosure

def cell(v):
    return str(v) if v is not None else ''

def row(*cols):
    return '\t'.join(cell(c) for c in cols)

lines = []
def r(*cols):
    lines.append(row(*cols))

def cont(desc, unit, qty, uprice, tprice):
    lines.append('\t\t\t\t\t\t\t' + '\t'.join(cell(c) for c in [desc, unit, qty, uprice, tprice]))

